True def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    background = max(set(v for row in out for v in row), key=lambda v: sum(row.count(v) for row in out))
    pairs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    pairs.append((color, r, c, dr, dc))

    for color, r, c, dr, dc in pairs:
        def runway(sr, sc, step_r, step_c):
            count = 0
            while 0 <= sr < h and 0 <= sc < w and out[sr][sc] in (background, color):
                count += 1
                sr += step_r
                sc += step_c
            return count

        before = runway(r - dr, c - dc, -dr, -dc)
        after = runway(r + 2 * dr, c + 2 * dc, dr, dc)
        if before > after and before >= 2:
            rr, cc = r - dr, c - dc
            while 0 <= rr < h and 0 <= cc < w and out[rr][cc] in (background, color):
                out[rr][cc] = color
                rr -= dr
                cc -= dc
        elif after > before and after >= 2:
            rr, cc = r + 2 * dr, c + 2 * dc
            while 0 <= rr < h and 0 <= cc < w and out[rr][cc] in (background, color):
                out[rr][cc] = color
                rr += dr
                cc += dc
    return out
